SELECT set_config('app.document_content_write_context','off',true);
SELECT set_config('request.jwt.claim.sub','ec000000-0000-0000-0000-000000000511',true);
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.documents WHERE id='ec000000-0000-0000-0000-000000000911'),1::bigint,'C1/A: own document metadata allowed');
SELECT is((SELECT count(*) FROM storage.objects WHERE name='ec000000-0000-0000-0000-000000000001/branches/ec000000-0000-0000-0000-000000000111/documents/ec000000-0000-0000-0000-000000000911.pdf'),1::bigint,'C1/A: own raw Storage metadata allowed');
